using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace first
{
    class Program
    {
        static void Main(string[] args)
        {
            int a, b, c,aMod,bMod,cMod;
            string str = Console.ReadLine();
            a=int.Parse(str);
            str=str.Replace("0", "");
            aMod = int.Parse(str);
            str = Console.ReadLine();
            b = int.Parse(str);
            str=str.Replace("0", "");
            bMod = int.Parse(str);
            c = a + b;
            cMod = int.Parse(c.ToString().Replace("0", ""));
            if ((aMod + bMod) == cMod)
                Console.WriteLine("YES");
            else
                Console.WriteLine("NO");
        }
    }
}
